 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigUseTlsAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isUseTls returns null on a freshly created holder.
     */
    public function testUseTlsNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigUseTlsAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUseTlsAssigned());
        $this->assertNull($holder->isUseTls());
    }
}
